package com.example.examplemod.journey;

import net.minecraft.nbt.*;
import java.util.*;
import static com.example.examplemod.journey.JourneyModel.*;

public final class JourneyCodec {
    public static CompoundTag point(Point p){var t=new CompoundTag();t.putString("Dimension",p.dimension());t.putInt("X",p.x());t.putInt("Y",p.y());t.putInt("Z",p.z());return t;}
    public static Point point(CompoundTag t){return new Point(t.getString("Dimension"),t.getInt("X"),t.getInt("Y"),t.getInt("Z"));}
    public static ListTag strings(Collection<String> values){var list=new ListTag();values.forEach(v->list.add(StringTag.valueOf(v)));return list;}
    public static List<String> strings(CompoundTag t,String key){var result=new ArrayList<String>();for(var raw:t.getList(key,Tag.TAG_STRING))result.add(raw.getAsString());return result;}
    public static CompoundTag marker(Marker m){var t=point(m.point);t.putString("Id",m.id);t.putString("Title",m.title);t.putString("Description",m.description);t.putString("Kind",m.kind.name());t.putInt("Radius",m.radius);t.putBoolean("Enabled",m.enabled);t.putBoolean("Newcomers",m.newcomers);t.putBoolean("OnMap",m.onMap);t.putBoolean("InWorld",m.inWorld);t.putInt("Tint",m.tint);t.putInt("Icon",m.icon);t.putInt("Size",m.size);t.putInt("Range",m.range);t.putString("AfterQuest",m.afterQuest);var route=new ListTag();m.route.forEach(p->route.add(point(p)));t.put("Route",route);return t;}
    public static Marker marker(CompoundTag t){var m=new Marker(t.getString("Id"),point(t));m.title=t.getString("Title");m.description=t.getString("Description");m.kind=Kind.valueOf(t.getString("Kind"));m.radius=Math.clamp(t.getInt("Radius"),1,64);m.enabled=t.getBoolean("Enabled");m.newcomers=t.getBoolean("Newcomers");m.onMap=!t.contains("OnMap")||t.getBoolean("OnMap");m.inWorld=!t.contains("InWorld")||t.getBoolean("InWorld");m.tint=t.getInt("Tint")&0xffffff;m.icon=t.contains("Icon")?Math.clamp(t.getInt("Icon"),0,7):m.kind.ordinal();m.size=t.contains("Size")?Math.clamp(t.getInt("Size"),8,16):10;m.range=t.contains("Range")?Math.clamp(t.getInt("Range"),16,160):72;m.afterQuest=t.getString("AfterQuest");for(var raw:t.getList("Route",10)){if(m.route.size()>=MAX_POINTS)throw new IllegalArgumentException("Route too long");m.route.add(point((CompoundTag)raw));}return m;}
    public static CompoundTag quest(Quest q){var t=new CompoundTag();t.putString("Id",q.id);t.putString("Title",q.title);t.putString("Description",q.description);t.putString("Marker",q.marker);t.putBoolean("Enabled",q.enabled);var list=new ListTag();for(var o:q.objectives){var v=new CompoundTag();v.putString("Id",o.id());v.putString("Kind",o.kind().name());v.putString("Target",o.target());v.putInt("Count",o.count());list.add(v);}t.put("Objectives",list);return t;}
    public static Quest quest(CompoundTag t){var q=new Quest(t.getString("Id"));q.title=t.getString("Title");q.description=t.getString("Description");q.marker=t.getString("Marker");q.enabled=t.getBoolean("Enabled");for(var raw:t.getList("Objectives",10)){var v=(CompoundTag)raw;if(q.objectives.size()>=MAX_OBJECTIVES)throw new IllegalArgumentException("Too many objectives");q.objectives.add(new Objective(v.getString("Id"),ObjectiveKind.valueOf(v.getString("Kind")),v.getString("Target"),v.getInt("Count")));}return q;}
    public static CompoundTag save(JourneyData d){var root=new CompoundTag();root.putInt("Version",1);var markers=new ListTag();d.markers.values().forEach(m->markers.add(marker(m)));root.put("Markers",markers);var quests=new ListTag();d.quests.values().forEach(q->quests.add(quest(q)));root.put("Quests",quests);var chains=new ListTag();for(var c:d.chains.values()){var t=new CompoundTag();t.putString("Id",c.id);t.putString("Title",c.title);t.putBoolean("Enabled",c.enabled);t.putBoolean("Automatic",c.automatic);t.put("Steps",strings(c.steps));chains.add(t);}root.put("Chains",chains);
        var players=new ListTag();d.players.forEach((id,p)->{var t=new CompoundTag();t.putUUID("Id",id);t.put("Completed",strings(p.completed));t.put("Met",strings(p.met));t.put("Accepted",strings(p.accepted));t.putString("Chain",p.chain);t.putString("ActiveQuest",p.activeQuest);t.putString("ActiveMarker",p.activeMarker);t.putBoolean("AutoStarted",p.autoStarted);t.putBoolean("Paused",p.paused);t.putBoolean("Graduated",p.graduated);players.add(t);});root.put("Players",players);return root;
    }
    public static JourneyData load(CompoundTag root){
        if(root.contains("Version")&&root.getInt("Version")!=1)throw new IllegalArgumentException("Unsupported journey data version");
        var d=new JourneyData();for(var raw:root.getList("Markers",10)){var m=marker((CompoundTag)raw);d.markers.put(m.id,m);}for(var raw:root.getList("Quests",10)){var q=quest((CompoundTag)raw);d.quests.put(q.id,q);}
        for(var raw:root.getList("Chains",10)){var t=(CompoundTag)raw;var c=new Chain(t.getString("Id"));c.title=t.getString("Title");c.enabled=t.getBoolean("Enabled");c.automatic=t.getBoolean("Automatic");c.steps.addAll(strings(t,"Steps"));d.chains.put(c.id,c);}
        for(var raw:root.getList("Players",10)){var t=(CompoundTag)raw;var p=new Progress();p.completed.addAll(strings(t,"Completed"));p.met.addAll(strings(t,"Met"));p.accepted.addAll(strings(t,"Accepted"));p.chain=t.getString("Chain");p.activeQuest=t.getString("ActiveQuest");p.activeMarker=t.getString("ActiveMarker");p.autoStarted=t.getBoolean("AutoStarted");p.paused=t.getBoolean("Paused");p.graduated=t.getBoolean("Graduated");d.players.put(t.getUUID("Id"),p);}return d;
    }
    private JourneyCodec(){}
}
